@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlate : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : double
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickupAddress : string
  + deliveryAddress : string
}

class Assignment {
  + date : date
}

Employee "0..*" -- "0..*" Order : assigns
Order "1" -- "1" Customer : client
Order "0..*" -- "0..1" PartnerCompany : placedWith
Order "1" -- "1" Vehicle : uses
Order "1" -- "1" Driver : completedBy
Order "1" -- "1" Planner : assignedBy

class Driver extends Employee {}

Vehicle "1" -- "0..*" Repair : undergoes
Repair "1" -- "1" RepairShop : at
Repair "1" -- "1" Employee : takenBy

Driver "1" -- "0..*" Assignment : executes
Assignment "1" -- "1" Order : for
Assignment "1" -- "1" Vehicle : with

@enduml

